using System;using System.Collections.Generic;using System.Linq;using System.IO;using KingmakerMountedCombat.Diagnostics;
namespace KingmakerMountedCombat.Tests{
internal static class AssistedFixtureAuthorityTests{
 const string Anchor="11111111-1111-4111-8111-111111111111",Minted="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",NewArea="fedcba9876543210fedcba9876543210";
 static int Main(){var t=new TestRunner();
 t.Run("closed exact assisted request",()=>{var f=new F();TestRunner.Equal(0,f.R.Validate().Count,string.Join(" | ",f.R.Validate()));});
 foreach(var kind in new[]{"missing","legacy","load","cap","auth","story","xp","money","route","source","ordinary","case","leaf","manual-name","schema"})t.Run("assisted protocol refuses "+kind,()=>{var f=new F();switch(kind){case"missing":f.R.AssistedFixture=null;break;case"legacy":f.R.Scenario="fixture-intake";break;case"load":f.R.AssistedFixture.ExpectedNativeLoadCount=1;break;case"cap":f.R.AssistedFixture.MaximumNativeWriteCount=4;break;case"auth":f.R.AssistedFixture.OwnerAuthorizationSha256=new string('f',64);break;case"story":f.R.AssistedFixture.StoryPolicy="any";break;case"xp":f.R.AssistedFixture.MaximumExperienceShortfall++;break;case"money":f.R.AssistedFixture.MaximumMoneyShortfall++;break;case"route":f.R.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;case"source":f.R.PersistenceLoad=f.R.Fixture.Working;break;case"ordinary":f.R.NativeBootstrap=new Chunk7NativeBootstrapSelection();break;case"case":f.R.AssistedFixture.Case="other";break;case"leaf":f.R.AssistedFixture.NativeInitialAutoLeaf="Auto_2.zks";break;case"manual-name":f.R.AssistedFixture.NativeManualName="KMC_other";break;case"schema":f.R.SchemaVersion=1;break;}TestRunner.True(f.R.Validate().Count>0,"Widened input admitted.");});
 t.Run("legacy request rejects assisted while untouched legacy remains valid",()=>{var f=new F();f.R.Scenario="fixture-intake";TestRunner.True(f.R.Validate().Count>0,"Assisted leaked.");f.R.AssistedFixture=null;TestRunner.Equal(0,f.R.Validate().Count,"Legacy guard changed.");});
 t.Run("metadata admits exact anchor but zero native loads",()=>{var f=new F();var a=f.Scope();TestRunner.True(a.ValidateArchiveIdentity(f.AnchorTarget,f.Root)==null,"Anchor enumeration refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.AnchorTarget,f.Root)!=null,"Load admitted.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Load spent.");});
 t.Run("early storage never consumes or freezes identity",()=>{var f=new F();var a=f.Scope();a.OpenBootstrapWindow();Refuse(()=>a.BeginWrite(f.Auto(),f.Root));TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Storage spent request.");TestRunner.Equal(0,a.BootstrapFreezeCount,"Storage minted identity.");});
 t.Run("origin refusal precedes native identity freeze",()=>{var f=new F();var a=f.Scope();a.OpenBootstrapWindow();f.Origin=false;TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Auto(null),f.Root)!=null,"Foreign origin admitted.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refusal spent.");TestRunner.Equal(0,a.BootstrapFreezeCount,"Refusal minted.");});
 t.Run("one initial Auto then write-disabled setup",()=>{var f=new F();var a=f.Scope();f.Initial(a);TestRunner.Equal("setup",a.AssistedPhase,"Initial phase not settled.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Auto(),f.Root)!=null,"Unselected Auto admitted.");TestRunner.Equal(1,a.AdmittedNativeWriteRequests,"Unselected write spent.");});
 t.Run("native levelup staging and replacement reach sole final Manual",()=>{var f=new F();var a=f.Scope();f.Initial(a);f.Level(a);f.Manual(a,7);TestRunner.Equal(3,a.AdmittedNativeWriteRequests,"Cumulative max3 differs.");TestRunner.Equal(1,a.AssistedLevelupWrites,"Levelup count differs.");TestRunner.Equal(2,a.AssistedReservationCount,"Reservation count differs.");TestRunner.Equal("complete",a.AssistedPhase,"Manual did not settle.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.ManualTarget(7),f.Root)!=null,"Fourth write admitted.");});
 t.Run("no levelup does not authorize unused extra Auto",()=>{var f=new F();var a=f.Scope();f.Initial(a);f.Manual(a,12);TestRunner.Equal(2,a.AdmittedNativeWriteRequests,"No-op path count differs.");TestRunner.Equal(0,a.AssistedLevelupWrites,"Invented levelup.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Auto(),f.Root)!=null,"Unused quota borrowed.");});
 foreach(var phase in new[]{"initial","levelup","manual"})t.Run("duplicate native request refuses "+phase,()=>{var f=new F();var a=f.Scope();RuntimeSaveTarget target;if(phase=="initial"){a.OpenBootstrapWindow();target=f.Auto(null);}else{f.Initial(a);if(phase=="levelup"){a.ReserveAssistedLevelup(f.R,f.Game,f.Manager,f.Auto());target=f.Auto();}else{a.ReserveAssistedManual(f.R,f.Game,f.Manager,7);target=f.ManualTarget(7);}}TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,target,f.Root)==null,"Selected request refused.");var count=a.AdmittedNativeWriteRequests;TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,target,f.Root)!=null,"Duplicate admitted.");TestRunner.Equal(count,a.AdmittedNativeWriteRequests,"Duplicate spent.");});
 foreach(var phase in new[]{"levelup","manual"})t.Run("reserved early storage refuses "+phase,()=>{var f=new F();var a=f.Scope();f.Initial(a);RuntimeSaveTarget target;if(phase=="levelup"){a.ReserveAssistedLevelup(f.R,f.Game,f.Manager,f.Auto());target=f.Stage();}else{a.ReserveAssistedManual(f.R,f.Game,f.Manager,7);target=f.ManualTarget(7);}Refuse(()=>a.BeginWrite(target,f.Root));TestRunner.Equal(1,a.AdmittedNativeWriteRequests,"Early storage spent.");});
 foreach(var kind in new[]{"request","game","manager","number0","duplicate","foreign-inventory","changed-anchor","output-present","enumeration-error"})t.Run("Manual reservation exact context "+kind,()=>{var f=new F();var a=f.Scope();f.Initial(a);var r=f.R;var g=f.Game;var m=f.Manager;var n=7;if(kind=="request")r=new F(false).R;if(kind=="game")g=new object();if(kind=="manager")m=new object();if(kind=="number0")n=0;if(kind=="duplicate")a.ReserveAssistedManual(r,g,m,n);if(kind=="foreign-inventory")V.Files.Add("foreign.zks",new string('e',64));if(kind=="changed-anchor")V.Files[f.R.Fixture.Working.FileName]=new string('e',64);if(kind=="output-present")V.Files.Add(Chunk7AssistedFixtureSelection.ManualLeaf(n),new string('e',64));if(kind=="enumeration-error")V.Throw=true;var count=a.AssistedReservationCount;Refuse(()=>a.ReserveAssistedManual(r,g,m,n));TestRunner.Equal(count,a.AssistedReservationCount,"Refused reservation published.");TestRunner.Equal(1,a.AdmittedNativeWriteRequests,"Reservation spent.");});
 foreach(var field in new[]{"token","case","baseline-length","suite-id","working-ticks","evidence-root"})foreach(var boundary in new[]{"match","write","storage","identity","readable","reserve"})t.Run("captured request mutation refuses "+field+" at "+boundary,()=>{var f=new F();var a=f.Scope();f.Initial(a);a.ReserveAssistedManual(f.R,f.Game,f.Manager,7);if(boundary=="storage")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.ManualTarget(7),f.Root)==null,"Setup write refused.");var count=a.AdmittedNativeWriteRequests;switch(field){case"token":f.R.TransactionToken=new string('e',64);break;case"case":f.R.AssistedFixture.Case="other";break;case"baseline-length":f.R.Fixture.Baseline.Length++;break;case"suite-id":f.R.QualificationSuite.SuiteId="changed-suite";break;case"working-ticks":f.R.Fixture.Working.LastWriteTimeUtcTicks++;break;case"evidence-root":f.R.EvidenceRoot=@"C:\KmcBootstrapVirtual\changed";break;}if(boundary=="match")TestRunner.True(!a.MatchesAssistedFixturePlan(f.R,f.Game,f.Manager),"Changed plan matched.");if(boundary=="write")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.ManualTarget(7),f.Root)!=null,"Changed write admitted.");if(boundary=="storage")Refuse(()=>a.BeginWrite(f.ManualTarget(7),f.Root));if(boundary=="identity")TestRunner.True(a.ValidateArchiveIdentity(f.Auto(),f.Root)!=null,"Changed archive identity admitted.");if(boundary=="readable")Refuse(()=>a.AssertReadableArchive(f.Auto().FullPath));if(boundary=="reserve")Refuse(()=>a.ReserveAssistedLevelup(f.R,f.Game,f.Manager,f.Auto()));TestRunner.Equal(count,a.AdmittedNativeWriteRequests,"Refusal spent quota.");});
 t.Run("foreign native owner cannot close gate",()=>{var f=new F();var a=f.Scope();Refuse(()=>a.CloseAssistedNativeGate(new object()));a.OpenBootstrapWindow();TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Auto(null),f.Root)==null,"Foreign close removed retained gate.");});
 t.Run("closed gate cannot issue any remaining quota",()=>{var f=new F();var a=f.Scope();a.CloseAssistedNativeGate(f.Owner);a.OpenBootstrapWindow();TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Auto(null),f.Root)!=null,"Closed origin granted write.");});
 KeyChecks(t);
 return t.Complete();}
 static string Shape(Type type)=>string.Join("|",type.GetProperties(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Instance).Where(p=>p.CanRead&&p.CanWrite).Select(p=>p.Name+":"+(Nullable.GetUnderlyingType(p.PropertyType)==null?p.PropertyType.Name:"Nullable<"+Nullable.GetUnderlyingType(p.PropertyType).Name+">")).OrderBy(x=>x,StringComparer.Ordinal));
 static Dictionary<string,object> KeyTargets(F f)=>new Dictionary<string,object>{{"request",f.R},{"baseline",f.R.Fixture.Baseline},{"working",f.R.Fixture.Working},{"write",f.R.Fixture.WriteAuthorization},{"suite",f.R.QualificationSuite},{"assisted",f.R.AssistedFixture}};
 static string Enc(Type type,object value){var method=typeof(PersistenceSaveAuthorization).GetMethod("AssistedScalar",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic,null,new[]{typeof(System.Text.StringBuilder),type},null);var text=new System.Text.StringBuilder();method.Invoke(null,new[]{(object)text,value});return text.ToString();}
 static void KeyChecks(TestRunner t){
  t.Run("exact admitted DTO shape RuntimeRequest",()=>TestRunner.True(Shape(typeof(RuntimeRequest))=="AcquiredManual:Chunk7AcquiredManualSelection|AssistedColdInventory:Chunk7AssistedColdInventorySelection|AssistedFixture:Chunk7AssistedFixtureSelection|BootstrapInventory:Chunk7BootstrapInventorySelection|Branch:String|Commit:String|CumulativeAcquisition:Chunk7CumulativeAcquisitionSelection|DllMvid:String|DllSha256:String|EvidenceRoot:String|Fixture:RuntimeFixtureIdentity|ManualDerived:Chunk7ManualDerivedSelection|ManualSeed:Chunk7ManualSeedSelection|NativeBootstrap:Chunk7NativeBootstrapSelection|ObserveWorkingDeserialization:Nullable<Boolean>|OrdinaryAcquisition:Chunk7OrdinaryAcquisitionSelection|OrdinaryField:Chunk7OrdinaryFieldSelection|OwnedPairs:Chunk7OwnedPairsSelection|PersistenceAlternate:RuntimeSaveDescriptor|PersistenceAreaTarget:RuntimeAreaTransitionTarget|PersistenceCase:String|PersistenceLoad:RuntimeSaveDescriptor|PersistenceReplayTargets:RuntimeAreaTransitionTarget[]|ProductVersion:String|Progression:Chunk7ProgressionSelection|QualificationSuite:RuntimeQualificationSuiteIdentity|RunId:String|SaveAccessAllowed:Boolean|SaveName:String|Scenario:String|Schema1DerivationSha256:String|SchemaVersion:Int32|SmallCalibration:Chunk7SmallCalibrationSelection|TransactionToken:String","DTO property shape changed; review every admitted key field."));
  t.Run("exact admitted DTO shape RuntimeFixtureIdentity",()=>TestRunner.True(Shape(typeof(RuntimeFixtureIdentity))=="Baseline:RuntimeSaveDescriptor|Working:RuntimeSaveDescriptor|WriteAuthorization:RuntimeSaveWriteAuthorization","DTO property shape changed; review every admitted key field."));
  t.Run("exact admitted DTO shape RuntimeSaveDescriptor",()=>TestRunner.True(Shape(typeof(RuntimeSaveDescriptor))=="Area:String|FileName:String|GameId:String|GameName:String|InternalName:String|LastWriteTimeUtcTicks:Int64|Length:Int64|Sha256:String","DTO property shape changed; review every admitted key field."));
  t.Run("exact admitted DTO shape RuntimeSaveWriteAuthorization",()=>TestRunner.True(Shape(typeof(RuntimeSaveWriteAuthorization))=="AllowedFileName:String|AllowedInternalName:String|BaselineImmutable:Boolean|Mode:String","DTO property shape changed; review every admitted key field."));
  t.Run("exact admitted DTO shape RuntimeQualificationSuiteIdentity",()=>TestRunner.True(Shape(typeof(RuntimeQualificationSuiteIdentity))=="SnapshotSha256:String|SuiteId:String","DTO property shape changed; review every admitted key field."));
  t.Run("exact admitted DTO shape Chunk7AssistedFixtureSelection",()=>TestRunner.True(Shape(typeof(Chunk7AssistedFixtureSelection))=="AssistancePolicy:String|AssistedSetupOnly:Boolean|BaseGameOnly:Boolean|Case:String|ExpectedNativeLoadCount:Int32|MaximumExperienceShortfall:Int32|MaximumMoneyShortfall:Int64|MaximumNativeWriteCount:Int32|MaximumStoryChoices:Int32|MaximumStorySeconds:Int32|MaximumTargetLevel:Int32|NativeInitialAutoLeaf:String|NativeManualName:String|OwnerAuthorizationSha256:String|StoryPolicy:String|TargetRangerLevel:Int32","DTO property shape changed; review every admitted key field."));
  var sample=new F();foreach(var pair in KeyTargets(sample))foreach(var p in pair.Value.GetType().GetProperties().Where(x=>x.CanRead&&x.CanWrite&&(x.PropertyType==typeof(string)||x.PropertyType==typeof(int)||x.PropertyType==typeof(long)||x.PropertyType==typeof(bool)||x.PropertyType==typeof(bool?)))){var group=pair.Key;var property=p;t.Run("captured scalar mutation "+group+"."+property.Name,()=>{var f=new F();var a=f.Scope();f.Initial(a);var target=KeyTargets(f)[group];var before=property.GetValue(target);object after=property.PropertyType==typeof(string)?(object)((string)before+"|:changed\n"):property.PropertyType==typeof(int)?(object)((int)before+1):property.PropertyType==typeof(long)?(object)((long)before+1):property.PropertyType==typeof(bool)?(object)!(bool)before:(object)(bool?)true;property.SetValue(target,after);TestRunner.True(!a.MatchesAssistedFixturePlan(f.R,f.Game,f.Manager),"Scalar changed without invalidating exact plan.");Refuse(()=>a.AssertReadableArchive(f.AnchorTarget.FullPath));TestRunner.True(a.AdmittedNativeWriteRequests==1&&a.AssistedReservationCount==0,"Mutation consumed authority.");});}
  t.Run("key encodes null empty delimiters without aliases",()=>{TestRunner.True(Enc(typeof(string),null)!=Enc(typeof(string),""),"null/empty collapsed");TestRunner.True(Enc(typeof(string),"a|b")+Enc(typeof(string),"c")!=Enc(typeof(string),"a")+Enc(typeof(string),"b|c"),"delimiter alias");TestRunner.True(Enc(typeof(string),"x:S-1:\0\n")!=Enc(typeof(string),"x:S-1:\0"),"control suffix alias");});
  t.Run("key type tags distinguish numbers strings booleans and nullable",()=>{var values=new[]{Enc(typeof(string),"1"),Enc(typeof(int),1),Enc(typeof(long),1L),Enc(typeof(bool),true),Enc(typeof(bool?),(bool?)true),Enc(typeof(bool?),null)};TestRunner.True(values.Distinct().Count()==values.Length,"Scalar type tags alias");});
  t.Run("key numeric encoding ignores current culture negative sign",()=>{var previous=System.Threading.Thread.CurrentThread.CurrentCulture;try{var culture=(System.Globalization.CultureInfo)System.Globalization.CultureInfo.InvariantCulture.Clone();culture.NumberFormat.NegativeSign="minus";System.Threading.Thread.CurrentThread.CurrentCulture=culture;TestRunner.True(Enc(typeof(int),-1)=="I-1;"&&Enc(typeof(long),-1L)=="L-1;","Culture changed numeric identity.");}finally{System.Threading.Thread.CurrentThread.CurrentCulture=previous;}});
  t.Run("accepted null empty string neighbor remains identity distinct",()=>{var f=new F();var a=f.Scope();f.R.SaveName="";TestRunner.True(!a.MatchesAssistedFixturePlan(f.R,f.Game,f.Manager),"Compatibility scalar null/empty drift accepted.");});
  foreach(var property in typeof(RuntimeRequest).GetProperties().Where(p=>p.CanRead&&p.CanWrite&&!p.PropertyType.IsValueType&&p.PropertyType!=typeof(string)&&p.Name!="Fixture"&&p.Name!="QualificationSuite"&&p.Name!="AssistedFixture")){var p=property;t.Run("foreign nested request selection refuses "+p.Name,()=>{var f=new F();var a=f.Scope();p.SetValue(f.R,p.PropertyType.IsArray?Array.CreateInstance(p.PropertyType.GetElementType(),0):Activator.CreateInstance(p.PropertyType));TestRunner.True(!a.MatchesAssistedFixturePlan(f.R,f.Game,f.Manager),"Foreign family object silently omitted from closed key.");});}
 }
 static void Refuse(Action action){var refused=false;try{action();}catch(InvalidOperationException){refused=true;}catch(IOException){refused=true;}catch(ArgumentException){refused=true;}TestRunner.True(refused,"Expected exact refusal.");}
 static RuntimeSaveDescriptor D(string name,string leaf,char hash)=>new RuntimeSaveDescriptor{InternalName=name,FileName=leaf,Sha256=new string(hash,64),Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Anchor,GameName="Anchor",Area=Area};
 sealed class F{
 internal object Game=new object(),Manager=new object(),Owner=new object();internal bool Origin=true;internal string Root=@"C:\KmcBootstrapVirtual\run\Saved Games";
 internal RuntimeRequest R=new RuntimeRequest{SchemaVersion=2,RunId="assisted-test",Scenario=Chunk7AssistedFixtureSelection.Scenario,AssistedFixture=new Chunk7AssistedFixtureSelection{
 Case=Chunk7AssistedFixtureSelection.CaseName,OwnerAuthorizationSha256=Chunk7AssistedFixtureSelection.AuthorizationSha256,BaseGameOnly=true,AssistedSetupOnly=true,
 StoryPolicy=Chunk7AssistedFixtureSelection.StoryPolicyName,AssistancePolicy=Chunk7AssistedFixtureSelection.AssistancePolicyName,ExpectedNativeLoadCount=0,MaximumNativeWriteCount=3,
 TargetRangerLevel=4,MaximumTargetLevel=8,MaximumStoryChoices=48,MaximumStorySeconds=300,MaximumExperienceShortfall=200000,MaximumMoneyShortfall=100000,
 NativeInitialAutoLeaf="Auto_1.zks",NativeManualName=Chunk7AssistedFixtureSelection.OutputName},Branch="codex/mounted-combat-chunk7-foundation",Commit=new string('1',40),ProductVersion=BuildIdentity.ProductVersion,DllSha256=new string('2',64),DllMvid=Anchor,TransactionToken=new string('3',64),EvidenceRoot=@"C:\KmcBootstrapVirtual\evidence",
 Fixture=new RuntimeFixtureIdentity{Baseline=D("KMC_AUTOMATION_BASELINE","Manual_298_KMC_AUTOMATION_BASELINE.zks",'a'),Working=D("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",'b'),WriteAuthorization=new RuntimeSaveWriteAuthorization{Mode="working-only",AllowedInternalName="KMC_AUTOMATION_WORKING",AllowedFileName="Manual_299_KMC_AUTOMATION_WORKING.zks",BaselineImmutable=true}},QualificationSuite=new RuntimeQualificationSuiteIdentity{SuiteId="assisted-suite",SnapshotSha256=new string('4',64)}};
 internal F(bool reset=true){if(reset){V.Files.Clear();V.Throw=false;V.Files.Add(R.Fixture.Working.FileName,new string('b',64));}}
 internal RuntimeSaveTarget T(string name,string leaf,string type,string area,string id=Minted,string gameName="Native")=>new RuntimeSaveTarget{InternalName=name,FileName=leaf,FullPath=Path.Combine(Root,leaf),SaveType=type,GameId=id,GameName=gameName,Area=area};
 internal RuntimeSaveTarget AnchorTarget=>T("KMC_AUTOMATION_WORKING",R.Fixture.Working.FileName,"Manual",Area,Anchor,"Anchor");
 internal RuntimeSaveTarget Auto(string area=NewArea)=>T("Autosave","Auto_1.zks","Auto",area);
 internal RuntimeSaveTarget Stage()=>T("Autosave","Auto_2.zks","Auto",NewArea);
 internal RuntimeSaveTarget ManualTarget(int n)=>T(Chunk7AssistedFixtureSelection.OutputName,Chunk7AssistedFixtureSelection.ManualLeaf(n),"Manual",NewArea);
 internal PersistenceSaveAuthorization Scope(){var a=new PersistenceSaveAuthorization(@"C:\KmcBootstrapVirtual\run",Anchor,"Anchor",new string('a',64),new[]{new PersistenceSaveEntry{FileName=R.Fixture.Working.FileName,InternalName="KMC_AUTOMATION_WORKING",SaveType="Manual",Area=Area,InitialSha256=new string('b',64)},new PersistenceSaveEntry{FileName="Auto_1.zks",InternalName="Autosave",SaveType="Auto",Area=NewArea,Writable=true,Campaign="B",AdmitsBeforeArea=true}},null,null,3,0);a.ConfigureAssistedFixture(R,Game,Manager,NewArea);a.BindAssistedNativeGate(R,Game,Manager,Owner,x=>Origin?null:"foreign origin");return a;}
 internal void Store(PersistenceSaveAuthorization a,RuntimeSaveTarget target,char hash){using(var lease=a.BeginWrite(target,Root)){V.Files[target.FileName]=new string(hash,64);lease.Complete();}}
 internal void Initial(PersistenceSaveAuthorization a){a.OpenBootstrapWindow();TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,Auto(null),Root)==null,"Initial request refused.");Store(a,Auto(),'d');a.ConfirmAssistedInitialAuto(R,Game,Manager,Auto());}
 internal void Level(PersistenceSaveAuthorization a){a.ReserveAssistedLevelup(R,Game,Manager,Auto());TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,Auto(),Root)==null,"Level request refused.");Store(a,Stage(),'e');using(var lease=a.BeginReplacement(Stage().FullPath,Auto().FullPath)){V.Files.Remove("Auto_2.zks");V.Files["Auto_1.zks"]=new string('e',64);lease.Complete();}a.ConfirmAssistedLevelup(R,Game,Manager,Auto());}
 internal void Manual(PersistenceSaveAuthorization a,int number){a.ReserveAssistedManual(R,Game,Manager,number);TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,ManualTarget(number),Root)==null,"Manual request refused.");Store(a,ManualTarget(number),'f');a.ConfirmAssistedManual(R,Game,Manager,ManualTarget(number));}
 }
