internal static class V{internal static readonly Dictionary<string,string> Files=new Dictionary<string,string>(StringComparer.Ordinal);internal static bool Throw;internal static void RequireDirectory(string path){if(!path.StartsWith(@"C:\KmcBootstrapVirtual\run",StringComparison.Ordinal))throw new IOException("foreign root");}internal static string Hash(string path){string hash;if(!Files.TryGetValue(Path.GetFileName(path),out hash))throw new IOException("missing virtual file");return hash;}}
internal static class AssistedDirectory{internal static bool Exists(string p)=>!p.EndsWith(".zks",StringComparison.Ordinal);internal static IEnumerable<string> EnumerateFileSystemEntries(string p){if(V.Throw)throw new IOException("enumeration");return V.Files.Keys.Select(x=>Path.Combine(p,x)).ToArray();}}
internal static class AssistedFile{internal static bool Exists(string p)=>V.Files.ContainsKey(Path.GetFileName(p));internal static void Delete(string p){V.Files.Remove(Path.GetFileName(p));}}
